    "question": "[Passage Excerpt: \"The 'Dutch Disease' occurs when massive natural resource discoveries lead to substantial currency appreciation. This foreign exchange shift makes a nation's non-resource manufacturing and agricultural exports uncompetitive, hollowing out the domestic industrial economy.\"]\n\nQuestion: Based on the passage concerning The Dutch Disease & Resource Curse, what is the principal finding or mechanism discussed?",
