    "question": "[Passage Excerpt: \"In eusocial hymenoptera (ants and bees), sterile worker castes sacrifice their own reproduction to raise their siblings. W.D. Hamilton explained this altruistic behavior through kin selection: because haplodiploidy makes sisters share 75% of their genes, helping sisters maximizes inclusive fitness ($rB > C$).\"]\n\nQuestion: According to Hamilton's rule of kin selection, altruistic sterile worker behavior evolves because _______.",
